import React, { useState } from "react";
import { Container, TextField, Button, Typography, Box, Paper, MenuItem, IconButton, InputAdornment, AppBar, Toolbar } from "@mui/material";
import { Visibility, VisibilityOff } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const schools = ["Engineering", "Business", "Arts"];
const courses = {
  Engineering: ["ENG101", "ENG102", "ENG103"],
  Business: ["BUS201", "BUS202", "BUS203"],
  Arts: ["ART301", "ART302", "ART303"],
};

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    regNumber: "",
    school: "",
    course: "",
    password: "",
    confirmPassword: "",
    showPassword: false,
  });
  
  const [errors, setErrors] = useState({});
  const [passwordCriteria, setPasswordCriteria] = useState({
    length: false,
    uppercase: false,
    lowercase: false,
    number: false,
    special: false,
  });

  const validatePassword = (password) => {
    setPasswordCriteria({
      length: password.length >= 8,
      uppercase: /[A-Z]/.test(password),
      lowercase: /[a-z]/.test(password),
      number: /[0-9]/.test(password),
      special: /[!@#$%^&*(),.?":{}|<>]/.test(password),
    });
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    
    if (name === "password") {
      validatePassword(value);
    }

    setErrors({ ...errors, [name]: value.trim() ? "" : "Required field" });
  };

  const handleTogglePassword = () => {
    if (formData.password) {
      setFormData({ ...formData, showPassword: !formData.showPassword });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let newErrors = {};
    
    Object.keys(formData).forEach((key) => {
      if (!formData[key]) newErrors[key] = "Required field";
    });
    
    if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = "Passwords do not match";
    }
    
    if (formData.regNumber.length !== 8 || !/^[a-zA-Z0-9]+$/.test(formData.regNumber)) {
      newErrors.regNumber = "Reg Number must be exactly 8 alphanumeric characters.";
    }
    
    if (!Object.values(passwordCriteria).every(Boolean)) {
      newErrors.password = "Password does not meet all criteria.";
    }
    
    setErrors(newErrors);
    
    if (Object.keys(newErrors).length === 0) {
      console.log("Form Submitted", formData);
      navigate("/dashboard");
    }
  };

  return (
    <Box sx={{ minHeight: "100vh", background: "rgba(100, 200, 225, 0.3)", backdropFilter: "blur(15px)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
      <AppBar position="fixed" color="primary">
        <Toolbar>
          <Typography variant="h6">SRC E-Voting System</Typography>
        </Toolbar>
      </AppBar>
      <Container maxWidth="sm" sx={{ mt: 12 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            Registration
          </Typography>
          <Box component="form" onSubmit={handleSubmit} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            <Box sx={{ display: "flex", gap: 2 }}>
              <TextField label="First Name" name="firstName" value={formData.firstName} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { boxShadow: '0 0 5px #1565c0' } }} helperText={errors.firstName} error={!!errors.firstName} />
              <TextField label="Last Name" name="lastName" value={formData.lastName} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { boxShadow: '0 0 5px #1565c0' } }} helperText={errors.lastName} error={!!errors.lastName} />
            </Box>
            <TextField label="Reg Number" name="regNumber" value={formData.regNumber} onChange={handleChange} required fullWidth helperText={errors.regNumber} error={!!errors.regNumber} />
            <Box sx={{ display: "flex", gap: 2, mt: 3 }}>
              <TextField select label="School" name="school" value={formData.school} onChange={handleChange} required fullWidth>
                {schools.map((school) => (
                  <MenuItem key={school} value={school}>{school}</MenuItem>
                ))}
              </TextField>
              <TextField select label="Course Code" name="course" value={formData.course} onChange={handleChange} required fullWidth disabled={!formData.school}>
                {formData.school && courses[formData.school].map((course) => (
                  <MenuItem key={course} value={course}>{course}</MenuItem>
                ))}
              </TextField>
            </Box>
            <TextField label="Password" name="password" type={formData.showPassword ? "text" : "password"} value={formData.password} onChange={handleChange} required fullWidth helperText={errors.password} error={!!errors.password} />
            <Box sx={{ color: "red", fontSize: "0.8rem" }}>
              {Object.entries(passwordCriteria).map(([key, met]) => (
                <Typography key={key} sx={{ color: met ? "green" : "red" }}>
                  {key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}
                </Typography>
              ))}
            </Box>
            <TextField label="Confirm Password" name="confirmPassword" type="password" value={formData.confirmPassword} onChange={handleChange} required fullWidth helperText={errors.confirmPassword} error={!!errors.confirmPassword} />
            <Button type="submit" variant="contained" color="success" fullWidth sx={{ height: "48px" }}>Register</Button>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default Register;
